export const meta = {
  name: 'slice2-simplify',
  description: 'Simplify docs/slice2-plan.md (stage-level reveal, no decisions during steps, queue runs to completion), recheck once, fix once',
  phases: [{ title: 'Simplify' }, { title: 'Recheck' }, { title: 'Fix' }],
}
const R = '/home/zhengyew/telelean'
const PLAN = R + '/docs/slice2-plan.md'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const LAST = R + '/verbatim_prompt_log/bundle_21/subagent_reports/slice2_planfix_workflow/agents/recheck_round2.json'
const SAFETY = `SAFETY AND RESOURCE RULES (mandatory): never change git state; no network, no installs, no Claude, no builds, no tests, no Lean. Do not touch packages/extension/dist or out. Read-only except where your task says you edit ONE file.`
const CRIT = { type: 'object', properties: { summary: { type: 'string' }, findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] }, where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['id', 'severity', 'where', 'problem', 'fix'] } } }, required: ['summary', 'findings'] }

const SIMPLIFICATIONS = `The integrator (on autopilot, logged as AP-24) decided to SIMPLIFY slice 2, because two fix rounds kept finding new major problems in the most intricate mechanisms. Apply these simplifications to the plan, REMOVING the machinery they make unnecessary (do not keep dead mechanisms "just in case"):
(1) STAGE-LEVEL REVEAL (replaces per-Result pre-sets, transitive reveal, twins, cas(R), masked per-target facts): all Result items of a stage are neutral until EVERY statement item and EVERY belief item of the session that is in review has been decided, or until the user presses Show result (which reveals all Results of the stage at once and is noted as "seen early"). Before the reveal, the Proposed view shows every proof-derived datum (glows, bands, solid arrows, established/rests-on-pending chips, Rests on, Used by, proof status, the stage report's verdicts, Claude's summary and "Assumed without asking", lemmas and other proof-only declarations, premise and arrow items that are part of a Result) AS IN THE SESSION BASE, i.e. computed from the base's facts for proofs, while statements and vocabulary come from the working copy. This hides at least as much as RV-6 requires. Hidden again when any statement or belief item returns to "in review" (then all Results are hidden again).
(2) NO DECISIONS WHILE A CLAUDE STEP RUNS (replaces pending writes, deferred decisions, decisions reaching the running step): while any step of the session runs (including a queue of several targets), the review list is read-only (statuses cannot change; Show result is not available); the user can still look, freeze is slice 3, Cancel step works. This is a small departure from RV-3 ("at any time") — note it.
(3) A FORMALIZE QUEUE RUNS TO COMPLETION BEFORE THE STAGE OPENS: several targets are proved in sequential steps, sources first, each with its own question and permitted set (B.1); the stage (and its items) opens when the last queued step ends (proved, not proved, given up, cancelled, failed). Cancel step cancels the running step and drops the rest of the queue (listed as "not run", with Retry). A mid-stage Formalize (RV-9) is a new queue that also runs to completion, then its items join the stage. Submit review runs one queue (one step per affected inference, sources first).
(4) Keep everything else that is sound and needed (items, statuses, RV-5 dependencies, RV-7 classes recomputed per judged state, decline options, Apply with final check and backstop, Exit, the session Undo stack sealed at every Claude step, crash-safe persistence, arrow items, Add premise items, the masked view's host-side enforcement — now with the simpler rule).
Then re-derive the sub-slices (each buildable by one agent; core ones strictly sequential), update the contracts (§2, §2.9) to match, delete the obsolete D2 decisions or mark them "withdrawn by AP-24", add the new decisions as "AUTOPILOT DECISION:" entries in §7.2, and add a dated §8 change-log entry. Also resolve the round-2 critic's findings that SURVIVE the simplification (read them in ${LAST}; many disappear with (1)-(3); say which).`

phase('Simplify')
const simplified = await agent(`${SAFETY} EXCEPTION: you edit exactly one file, ${PLAN}.\n\nRead ${PLAN} fully and the spec ${SPEC} (slice 2's clauses: ES-1..ES-9 for Formalize-started sessions, RV-1..RV-13, DO-0/1/3, EN-1..EN-4, UN-4..UN-6, CM-6, Appendix B).\n\n${SIMPLIFICATIONS}\n\nYour final message: what you removed, what you changed, the new sub-slice list (id + one line), the new and withdrawn decisions (one line each), and for each round-2 finding: gone with the simplification / fixed / still open (why).`, { label: 'simplify:plan', phase: 'Simplify' })

phase('Recheck')
const crit = await agent(`${SAFETY}\n\nCritique the telelean slice-2 plan at ${PLAN} FRESHLY and adversarially. It was just simplified (its §8 change log says how: stage-level reveal, no decisions while a step runs, a Formalize queue runs to completion before the stage opens). Context: the spec is ${SPEC}. Lenses: (1) SOUNDNESS — can anything become assumed without the user's individual Accept, can a result show before the meaning check, can a state no check judged be applied, can a proof rest on something its question does not allow, can the user's decisions be lost on rollback/reload/crash? (2) IMPLEMENTABILITY — are the contracts complete, consistent and type-correct against the current code (read it), is each sub-slice buildable by one agent? Report only real problems with concrete fixes. Do not re-raise the deliberate simplifications themselves as problems unless they break soundness.`, { label: 'recheck:simplified', phase: 'Recheck', schema: CRIT })

const must = (crit?.findings ?? []).filter((f) => f.severity === 'blocker' || f.severity === 'major')
log(`recheck: ${crit?.findings?.length ?? 0} findings, ${must.length} blocker/major`)
let fixed = null
if ((crit?.findings ?? []).length > 0) {
  phase('Fix')
  fixed = await agent(`${SAFETY} EXCEPTION: you edit exactly one file, ${PLAN}.\n\nFix the telelean slice-2 plan (${PLAN}) for the critic's findings below: every blocker and major, and the cheap minors. Keep the AP-24 simplifications (stage-level reveal, no decisions while a step runs, queues run to completion). Mark design choices "AUTOPILOT DECISION:" in §7.2 and add a dated §8 entry. Final message: per finding fixed / not fixed (why), and the final sub-slice list.\n\n=== FINDINGS ===\n${JSON.stringify(crit.findings, null, 1)}`, { label: 'fix:simplified', phase: 'Fix' })
}
return { simplified, crit, fixed }
